WITH catalog_daily AS ( SELECT d.d_date AS sale_date, SUM(cs.cs_net_profit) AS daily_net_profit, SUM(cs.cs_ext_sales_price) AS daily_sales, AVG(cs.cs_net_profit / NULLIF(cs.cs_ext_sales_price, 0)) AS avg_profit_margin, AVG(date_diff('day', d.d_date, d_ship.d_date)) AS avg_ship_delay FROM catalog_sales cs JOIN date_dim d ON cs.cs_sold_date_sk = d.d_date_sk JOIN date_dim d_ship ON cs.cs_ship_date_sk = d_ship.d_date_sk GROUP BY d.d_date ) SELECT sale_date, daily_net_profit, daily_sales, avg_ship_delay, CASE WHEN avg_profit_margin > 0.5 THEN 'High' WHEN avg_profit_margin > 0.3 THEN 'Medium' ELSE 'Low' END AS profit_margin_category, SUM(daily_net_profit) OVER (ORDER BY sale_date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_net_profit, RANK() OVER (ORDER BY daily_net_profit DESC) AS profit_rank FROM catalog_daily ORDER BY sale_date
